// Traduce lo que manda Kommo a campos limpios.
//
// Kommo envia x-www-form-urlencoded con claves tipo message[add][0][text],
// y el intermediario lo reenvia intacto: aqui llega igual que salio de Kommo.
const b = $input.first().json.body ?? {};
const g = (k) => b['message[add][0][' + k + ']'] ?? null;

// Solo se reacciona a lo que ENTRA. Un 'outgoing' es lo que escribio la
// encargada o el propio agente: contestarlo seria hablar solo.
if (g('type') !== 'incoming') {
  return [];
}

const epoch = Number(g('created_at'));

return [{
  json: {
    msg_id:       g('id'),
    lead_id:      g('entity_id') ?? g('element_id'),
    contacto_id:  g('contact_id'),
    chat_id:      g('chat_id'),
    talk_id:      g('talk_id'),
    texto:        g('text'),
    // De donde entro: telegram en pruebas, whatsapp en produccion. Sirve
    // para excluir el trafico de prueba de los reportes.
    origen:       g('origin'),
    autor:        b['message[add][0][author][name]'] ?? null,
    tipo_mensaje: g('message_type'),
    adjunto_tipo: b['message[add][0][attachment][type]'] ?? null,
    adjunto_url:  b['message[add][0][attachment][link]'] ?? b['message[add][0][attachment][url]'] ?? null,
    creado_at:    Number.isFinite(epoch) ? new Date(epoch * 1000).toISOString() : null,
    subdominio:   b['account[subdomain]'] ?? null,
  },
}];
